node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Look for flight-related tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('All tables:', tables.map(t=>t.name));

// Check for a flights/flight inventory table
for (const t of tables) {
  if (t.name.toLowerCase().includes('flight') && !t.name.includes('booking')) {
    const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
    console.log('\n--- ' + t.name + ' columns:', cols.map(c=>c.name).join(', '));
    const rows = db.prepare('SELECT * FROM ' + t.name).all();
    console.log('Row count:', rows.length);
    console.log('All rows:', JSON.stringify(rows, null, 2));
  }
}
" 2>&1
